import{_ as t,o as a,c as s,ak as i}from"./chunks/framework.DIgTxpuq.js";const p=JSON.parse('{"title":"Contributing","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"contributing/index.md","filePath":"contributing/index.md","lastUpdated":1794042109000}'),o={name:"contributing/index.md"};function n(r,e,l,h,d,u){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Thanks for helping out with the dice roller!</p><p>The following is a set of guidelines for contributing to the library. They explain the process to get started, and ensure that it&#39;s as easy as possible for people to work with the project.</p><h2 id="code-of-conduct" tabindex="-1">Code of Conduct <a class="header-anchor" href="#code-of-conduct" aria-label="Permalink to &quot;Code of Conduct&quot;">​</a></h2><p>Check out our <a href="./code-of-conduct.html">Code of Conduct</a>.</p><h2 id="i-have-a-question" tabindex="-1">I have a question <a class="header-anchor" href="#i-have-a-question" aria-label="Permalink to &quot;I have a question&quot;">​</a></h2><p>Please use the <a href="https://github.com/dice-roller/rpg-dice-roller/discussions" target="_blank" rel="noreferrer">GitHub discussion board</a> to raise questions.</p><h2 id="how-to-contribute" tabindex="-1">How to contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How to contribute&quot;">​</a></h2><h3 id="reporting-bugs" tabindex="-1">Reporting bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;Reporting bugs&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Before raising a ticket, please check it hasn&#39;t already been raised!</p></div><p>If you find a bug, please let us know.</p><h4 id="before-submitting-a-bug-report" tabindex="-1">Before submitting a bug report <a class="header-anchor" href="#before-submitting-a-bug-report" aria-label="Permalink to &quot;Before submitting a bug report&quot;">​</a></h4><ul><li><a href="https://github.com/dice-roller/rpg-dice-roller/issues?q=is%3Aissue+label%3Abug" target="_blank" rel="noreferrer">Search through existing tickets</a> to see if the issue has already been reported. <ul><li>If it has, and the issue is still <em>open</em>, add a comment to it, rather than creating a new ticket.</li><li>If it has, and the issue is <em>closed</em>, see if any suggested fix resolves the issue for you.</li></ul></li></ul><h4 id="how-to-submit-a-bug-report" tabindex="-1">How to submit a bug report <a class="header-anchor" href="#how-to-submit-a-bug-report" aria-label="Permalink to &quot;How to submit a bug report&quot;">​</a></h4><p>Bugs are tracked as GitHub issues, and you can <a href="https://github.com/dice-roller/rpg-dice-roller/issues/new/choose" target="_blank" rel="noreferrer">report a bug through GitHub</a>.</p><p>Explain the problem in as much detail as possible, including any additional details that could help to reproduce the problem.</p><ul><li><strong>Use a clear and descriptive title</strong> for the issue, that identifies the problem.</li><li><strong>Describe the exact steps which reproduce the problem</strong> with as much detail as possible.</li><li><strong>Provide specific examples to demonstrate the steps.</strong> Include links to source code, or copy/paste code snippets. If providing code snippets, please use <a href="https://help.github.com/en/github/writing-on-github/creating-and-highlighting-code-blocks" target="_blank" rel="noreferrer">Markdown code blocks</a>.</li><li><strong>Describe the behaviour that you observed after following the steps</strong> and explain why this is a problem.</li><li><strong>Describe the behaviour that you expected to see and why.</strong></li><li><strong>Include any screenshots</strong> if relevant.</li><li><strong>If you receive any error messages</strong>, <code>console</code> output, or similar, please include them.</li><li><strong>Provide the library version number</strong> that you&#39;re using. If it&#39;s not the latest version, can you reproduce the problem in the latest release?</li></ul><h3 id="suggesting-improvements-and-new-features" tabindex="-1">Suggesting improvements and new features <a class="header-anchor" href="#suggesting-improvements-and-new-features" aria-label="Permalink to &quot;Suggesting improvements and new features&quot;">​</a></h3><p>We&#39;d love to hear any ideas you&#39;ve got for new features or improvements. Following these guidelines helps us to understand your suggestion better.</p><h4 id="before-submitting-a-feature-suggestion" tabindex="-1">Before submitting a feature suggestion <a class="header-anchor" href="#before-submitting-a-feature-suggestion" aria-label="Permalink to &quot;Before submitting a feature suggestion&quot;">​</a></h4><ul><li><strong>Check you&#39;re using the latest version.</strong> The feature may have been added in a newer version.</li><li><a href="https://github.com/dice-roller/rpg-dice-roller/issues?q=is%3Aissue+label%3Aenhancement,suggestion,question" target="_blank" rel="noreferrer">Search through existing tickets</a> to see if the feature has already been suggested. If it has, add a comment to the existing one, rather than creating a new one.</li></ul><h4 id="how-to-submit-a-feature-suggestion" tabindex="-1">How to submit a feature suggestion <a class="header-anchor" href="#how-to-submit-a-feature-suggestion" aria-label="Permalink to &quot;How to submit a feature suggestion&quot;">​</a></h4><p>Feature suggestions are tracked as GitHub tickets, and you can <a href="https://github.com/dice-roller/rpg-dice-roller/issues/new/choose" target="_blank" rel="noreferrer">suggest a feature through GitHub</a>.</p><ul><li><strong>Use a clear and descriptive title</strong> for the ticket, that identifies the suggestion.</li><li><strong>Provide a step-by-step description of the feature</strong> with as much detail as possible.</li><li><strong>Provide any relevant examples to demonstrate the feature</strong>, such as code snippets.</li><li><strong>Describe the current behaviour</strong> and <strong>explain the behaviour you&#39;d like to see instead</strong> and why.</li><li><strong>Include any screenshots</strong> if relevant.</li><li><strong>Explain why the feature would be useful</strong></li></ul><h3 id="contributing-code" tabindex="-1">Contributing code <a class="header-anchor" href="#contributing-code" aria-label="Permalink to &quot;Contributing code&quot;">​</a></h3><p>If you want to help out with the development itself then please dive in.</p><h4 id="finding-something-to-work-on" tabindex="-1">Finding something to work on <a class="header-anchor" href="#finding-something-to-work-on" aria-label="Permalink to &quot;Finding something to work on&quot;">​</a></h4><p>If you&#39;re unsure where to begin, you can start by having a look at the tickets flagged as <a href="https://github.com/dice-roller/rpg-dice-roller/issues?q=is%3Aissue+is%3Aopen+label%3A%22help+wanted%22,%22good+first+issue%22" target="_blank" rel="noreferrer">&quot;help wanted&quot; or &quot;good first issue&quot;</a>, and see if you can help with any of them.</p><p>If there aren&#39;t any flagged as with either label, that doesn&#39;t mean we don&#39;t want your help! Generally, we&#39;re happy for people to dig into any ticket that hasn&#39;t been assigned to someone. A ticket that has been assigned means that someone else is working on it.</p><p>So have a look around the open tickets and see if you feel as though you can help with any of them.</p><p>If you&#39;ve got an idea for a feature, but there isn&#39;t a ticket for it, feel free to <a href="#suggesting-improvements-and-new-features">create one</a> and assign it to yourself. This way, it&#39;s easier to keep track on what is being worked on, and we can try to ensure that multiple people aren&#39;t unknowingly working on the same thing.</p><h4 id="setting-up" tabindex="-1">Setting up <a class="header-anchor" href="#setting-up" aria-label="Permalink to &quot;Setting up&quot;">​</a></h4><p>The code is stored in a Git repository. To get started either <a href="https://github.com/dice-roller/rpg-dice-roller" target="_blank" rel="noreferrer">clone or fork the repository</a>.</p><p>Make sure that you check out the <code>develop</code> branch, or create a <code>feature</code> / <code>hotfix</code> branch for the task you&#39;re working on, and <em>not</em> the <code>main</code> branch.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You should <strong>never</strong> work directly on the <code>main</code> branch. You should work on either the <code>develop</code> branch or a <code>feature</code> branch.</p><p>See the <a href="#branching-model">Branching model</a> section for more information.</p></div><h4 id="file-structure" tabindex="-1">File structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File structure&quot;">​</a></h4><p>The project file structure is split up into logical groups:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/</span></span>
<span class="line"><span>|- demo/</span></span>
<span class="line"><span>|- lib/</span></span>
<span class="line"><span>   |- esm/</span></span>
<span class="line"><span>   |- umd/</span></span>
<span class="line"><span>|- src/</span></span>
<span class="line"><span>|- tests/</span></span></code></pre></div><ul><li><p><code>root</code> contains mostly meta files, such as the <code>.babelrc</code>, <code>eslintrc.json</code>. <code>rollup.config.js</code> and other files used for the generation of the library.</p></li><li><p><code>lib</code> contains the compiled Javascript files, in both EcmaScript and UMD versions, in the <code>esm</code> and <code>umd</code> directories respectively.</p><p>Do <strong>not</strong> manually change the files in this directory as any changes will be overwritten.</p></li><li><p><code>src</code> is where the magic happens. This contains all the source Javascript ES modules that get compiled into the <code>lib</code> directory. It is these files that you should modify.</p></li><li><p><code>tests</code> contain <a href="#testing-your-code">Jest tests</a>. If you make changes to the source code, you should update / add tests to cover the changes.</p></li></ul><h4 id="compiling-and-building-the-code" tabindex="-1">Compiling and building the code <a class="header-anchor" href="#compiling-and-building-the-code" aria-label="Permalink to &quot;Compiling and building the code&quot;">​</a></h4><p>If you want to see what how your code functions, you&#39;ll need to compile the source code to the <code>lib</code> directory. There are several ways of doing this, depending on the required outcome.</p><p>There are several scripts to help:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># compile compressed / minified the ES and UMD files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># compile un-compressed version of the ES and UMD files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:dev</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># watch the \`src\` directory for changes and compile un-compressed ES files on change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span></span></code></pre></div><h4 id="testing-your-code" tabindex="-1">Testing your code <a class="header-anchor" href="#testing-your-code" aria-label="Permalink to &quot;Testing your code&quot;">​</a></h4><p>We utilise both a <a href="#javascript-style-guide">JavaScript linter</a> and a <a href="#testing">testing framework</a> to ensure that all code conforms to certain standards and any new code doesn&#39;t break existing code, or otherwise behave unexpectedly.</p><p>You do <strong>not</strong> need to build / compile the code before linting or testing. Both the linter and tests run on the original source code.</p><p><strong>All code must pass both the linter and the tests.</strong> You can read more about them in the <a href="#styles-and-standards">Styles and standards</a> section.</p><h3 id="pull-requests" tabindex="-1">Pull requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull requests&quot;">​</a></h3><p>When creating a pull request, there are several things that need to be considered, to ensure that the quality of the library is kept, and that the code remains readable and manageable</p><p>Please follow these steps so that your pull request can be considered by the maintainers:</p><ul><li>Ensure all <a href="#testing">tests</a> pass locally before creating a pull request. If they do not, explain the reason in description of the pull request.</li><li>If the pull request relates to a ticket, ensure that the ticket number is referenced in the description of the pull request.</li><li>Provide a description of what the pull request is trying to achieve. If there is a related ticket, then the description can be brief. Otherwise, please provide enough detail for the reviewer to understand what bug it fixes, or feature it implements, and why.</li><li>Follow the <a href="#styles-and-standards">style guides</a>.</li><li>After submitting your pull request, verify that all <a href="https://help.github.com/articles/about-status-checks/" target="_blank" rel="noreferrer">status checks</a> are passing.</li></ul><div class="tip custom-block"><p class="custom-block-title">What if the tests / status checks are failing?</p><p>Check what is failing. If you believe that the failure is unrelated to your change, please leave a comment on the pull request explaining why you believe the failure is unrelated. A maintainer can re-run the status checks and determine if it&#39;s a false positive, or otherwise unrelated to your changes.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You should <strong>never</strong> work directly on the <code>main</code> branch. Any pull requests on to <code>main</code> will, unfortunately, have to be rejected, and you&#39;ll have to re-create it on <code>develop</code>.</p><p>See the <a href="#branching-model">Branching model</a> section for more information.</p></div><h2 id="styles-and-standards" tabindex="-1">Styles and standards <a class="header-anchor" href="#styles-and-standards" aria-label="Permalink to &quot;Styles and standards&quot;">​</a></h2><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h3><h4 id="branching-model" tabindex="-1">Branching model <a class="header-anchor" href="#branching-model" aria-label="Permalink to &quot;Branching model&quot;">​</a></h4><p>We use the <a href="https://nvie.com/posts/a-successful-git-branching-model/" target="_blank" rel="noreferrer">git-flow branching model</a>. This means that there is always a <code>main</code> branch and a <code>develop</code> branch, and there may be other branches that follow the git-flow naming conventions.</p><ul><li>The <code>main</code> branch is the current latest release, and should <em>only be modified when making a release</em>.</li><li>The <code>develop</code> branch is where all the fun happens, and where we can work and make our changes (Although these should generally be done on a feature branch).</li></ul><h4 id="commit-messages" tabindex="-1">Commit messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to &quot;Commit messages&quot;">​</a></h4><ul><li>Use the present tense (e.g. &quot;Add feature&quot; not &quot;Added feature&quot;).</li><li>Use the imperative mood (e.g. &quot;Enhance fudge die rolls&quot; not &quot;Enhances fudge die rolls&quot;).</li><li>Limit the first line to 72 characters or fewer.</li><li>Reference relevant ticket numbers after the first line.</li></ul><h3 id="javascript-style-guide" tabindex="-1">JavaScript style guide <a class="header-anchor" href="#javascript-style-guide" aria-label="Permalink to &quot;JavaScript style guide&quot;">​</a></h3><p>All JavaScript must adhere to the <a href="https://airbnb.io/javascript/" target="_blank" rel="noreferrer">Airbnb standard style</a>. This is to make sure that the code is readable and more maintainable for everyone.</p><p>We use <a href="https://eslint.org/" target="_blank" rel="noreferrer">ESLint</a> to ensure that the syntax is correct and meets the standards.</p><p>You can check if the code conforms to the standards by running the following in the console:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span></code></pre></div><p>If there are problems, it will show you the files and line numbers for each issue.</p><h3 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h3><p>We use <a href="https://jestjs.io/" target="_blank" rel="noreferrer">Jest</a> to test the library. The tests can be found in the <code>/tests</code> directory.</p><p>When writing tests, ensure that they are thoughtfully-worded, and well-structured, so that it is both easy to understand and maintain.</p><p>You can check if the code passes all the tests by running the following in the console:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>This runs the <a href="#javascript-style-guide">JavaScript Linter</a> first, and then the tests, so if the linter fails, then the tests will not be run.</p><h3 id="use-of-ai" tabindex="-1">Use of AI <a class="header-anchor" href="#use-of-ai" aria-label="Permalink to &quot;Use of AI&quot;">​</a></h3><p>You’re welcome to use AI tools to help write code, improve documentation, or draft issues and comments. The same contribution guidelines apply whether or not you use AI.</p><p>Please review and verify anything you submit. If you’re reporting a bug, check that you can reproduce it. If you’re opening a pull request, make sure you understand the changes, can explain why they’re needed, and have run the relevant tests. Be prepared to answer questions about your contribution.</p><p>Maintainers may close or remove spam, irrelevant submissions, or bulk-generated content posted without meaningful review. Accounts that repeatedly post this material or engage in deliberate abuse may be blocked from participating in the project.</p>`,76)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
